{
  "application": "ppt-generation",
  "case_id": "case-paper-smolvlm",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 9,
    "audience": "ML researchers, on-device AI engineers, and graduate students working on efficient multimodal models",
    "tone": "technical, data-forward, concise"
  },
  "brief": {
    "title": "SmolVLM: Redefining Small and Efficient Multimodal Models",
    "one_liner": "SmolVLM is a family of compact vision-language models that achieve competitive performance with dramatically lower memory footprints through strategic architectural optimizations.",
    "goal": "Understand SmolVLM's key design decisions — compute allocation, token compression, and training data curation — and how they enable sub-1GB inference for multimodal tasks on edge devices."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "SmolVLM: Redefining Small and Efficient Multimodal Models",
      "objective": "Cover slide with paper title, authors (Hugging Face & Stanford), and a key visual showing the SmolVLM architecture or logo. Set the context of efficient on-device VLMs."
    },
    {
      "id": "problem-motivation",
      "title": "Large VLMs Are Powerful but Impractical for Edge Deployment",
      "objective": "Frame the problem: state-of-the-art VLMs require massive compute and memory, limiting mobile/edge use. Contrast parameter counts and RAM usage of existing models. Use a concise bullet list or comparison graphic."
    },
    {
      "id": "architecture-overview",
      "title": "SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone",
      "objective": "Show the SmolVLM architecture pipeline diagram (image splitting → vision encoder → pixel shuffle → linear projection → SmolLM2). Reference the architecture figure. Explain the flow in 3-4 key steps."
    },
    {
      "id": "compute-allocation",
      "title": "Smaller Vision Encoders Outperform Larger Ones in Compact VLMs",
      "objective": "Present Finding 1: balanced encoder-LM parameter allocation matters. Show how a 93M SigLIP-B/16 outperforms the 428M SigLIP-SO400M for the smallest LMs. Use a bar chart or comparison visual referencing the experimental results."
    },
    {
      "id": "token-compression",
      "title": "Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models",
      "objective": "Explain pixel shuffle and its impact on token count. Show that small VLMs benefit from r=4 compression while larger models prefer r=2. Include the pixel shuffle diagram and performance comparison across shuffle factors."
    },
    {
      "id": "context-length-scaling",
      "title": "Extending Context from 2K to 16K Tokens Unlocks Higher Image Resolution",
      "objective": "Present Finding 2: performance improves significantly with extended context length from 2K to 16K tokens. Explain the RoPE base adjustment from 10K to 273K and fine-tuning on mixed long/short-context data. Note that the 2.2B model uses 16K context while smaller variants use 8K. Use a concise bullet list or diagram to illustrate the context extension strategy and its qualitative impact."
    },
    {
      "id": "benchmark-performance",
      "title": "SmolVLM Achieves Competitive Performance at Sub-1GB to 4.9GB RAM",
      "objective": "Present the full benchmark comparison table across Single-Image, Multi-task, and Video benchmarks for SmolVLM 256M/500M/2.2B vs. Best Efficient OS baselines (Molmo-A1B-7B, InternVL2-2B). Highlight the average scores (44.0%, 51.0%, 59.8%) and RAM usage (0.8GB to 4.9GB vs. 27.7GB for Molmo-A1B-7B). Note that SmolVLM-256M surpasses the 300× larger Idefics-80B per the paper's key findings. Use a data table visualization."
    },
    {
      "id": "on-device-deployment",
      "title": "Real-Time Inference on iPhones: Up to 80 Tokens/Second on Apple Silicon",
      "objective": "Show on-device deployment results: HuggingSnap mobile app screenshots and throughput charts across Apple Silicon devices. Highlight tokens-per-second at different model sizes and batch sizes. Reference the performance graphs."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Design Principles for Efficient Multimodal Models",
      "objective": "Summarize 4-5 actionable findings: (1) balance encoder-LM compute, (2) extend context length, (3) use aggressive token compression for small models, (4) sub-1GB inference is achievable, (5) fully open-source release. End with implications for on-device AI."
    }
  ]
}
